void AgentHost::request_account()
{
    if (!m_model_source)
        return;
    m_model_source->fetch_account([this](std::optional<json> account) {
        // No answer, or a refused one, keeps the last answer; signing out clears it.
        const std::vector<std::string> configured = m_model_source->configured_providers();
        const bool signed_in = std::any_of(configured.begin(), configured.end(), [](const std::string& provider) {
            const ProviderProfile* profile = profile_for(provider);
            return profile != nullptr && profile->account_sign_in;
        });
        if (account)
            m_account = std::move(account);
        else if (!signed_in)
            m_account.reset();
        else
            return;
        send_account();
        send_active_chat_model();
    });
}

void AgentHost::send_account()
{
    if (m_handshake)
        send_envelope(Protocol::kAccount,
                      json{{"account", m_account ? *m_account : json()}, {"chatTitles", usage_chat_titles()}}.dump());
}

void AgentHost::request_account_box()
{
    // Signing in or out asks again, so only the latest request is answered.
    const unsigned request = ++m_account_box_request;
    auto answer = [this, request](std::optional<std::string> html) {
        if (request == m_account_box_request && m_handshake)
            send_envelope(Protocol::kAccountBox, json{{"html", html ? json(*html) : json()}}.dump());
    };
    if (m_model_source)
        m_model_source->fetch_account_box(std::move(answer));
    else
        answer(std::nullopt);
}

namespace {

// {"<gateway chat id>": "<title>"}, or no file before the first title.
json read_chat_titles(const std::string& path)
{
    const std::filesystem::path file = std::filesystem::u8path(path);
    if (!std::filesystem::exists(file))
        return json::object();
    std::ifstream in(file, std::ios::binary);
    if (!in)
        throw RuntimeError("The chat titles file could not be opened: " + std::string(std::strerror(errno)));
    json titles = json::parse(in);
    if (!titles.is_object())
        throw RuntimeError("The chat titles file holds " + std::string(titles.type_name()) + ", not an object");
    return titles;
}

} // namespace

void AgentHost::remember_chat_titles()
{
    if (m_chat_titles_file.empty())
        return;
    const ProjectStateDocument& document = m_persistence.document();
    std::map<std::string, std::string> changed;
    for (const ConversationInfo& info : document.conversations()) {
        // A chat with no message yet has spent nothing.
        if (info.preview.empty())
            continue;
        const std::string id   = gateway_chat_id(chat_key(document, info.id));
        const auto        kept = m_chat_titles_kept.find(id);
        if (kept == m_chat_titles_kept.end() || kept->second != info.title)
            changed.emplace(id, info.title);
    }
    if (changed.empty())
        return;
    // Read again before writing: another window may have added its chats.
    json titles = read_chat_titles(m_chat_titles_file);
    for (const auto& [id, title] : changed)
        titles[id] = title;
    const std::filesystem::path path = std::filesystem::u8path(m_chat_titles_file);
    const std::filesystem::path temp = path.string() + ".tmp";
    std::filesystem::create_directories(path.parent_path());
    {
        std::ofstream out(temp, std::ios::binary | std::ios::trunc);
        out << titles.dump();
        out.close();
        if (!out)
            throw RuntimeError("The chat titles file could not be written: " + std::string(std::strerror(errno)));
    }
    std::filesystem::rename(temp, path);
    for (auto& [id, title] : changed)
        m_chat_titles_kept[id] = std::move(title);
}

json AgentHost::usage_chat_titles() const
{
    json found = json::object();
    if (!m_account || m_chat_titles_file.empty())
        return found;
    const json titles = read_chat_titles(m_chat_titles_file);
    // A report's row names itself and has no chat; a request of no chat has
    // a null one.
    for (const json& row : m_account->at("usage_30d").at("activity")) {
        const auto chat = row.find("chat_id");
        if (chat == row.end() || !chat->is_string())
            continue;
        const auto title = titles.find(chat->get<std::string>());
        if (title != titles.end())
            found[chat->get<std::string>()] = *title;
    }
    return found;
}

bool AgentHost::use_chat_model(const std::string& conversation_id, const ConversationMessage& assistant, bool by_person)
{
    if (!m_model_source)
        return true;
    ProjectStateDocument& document = m_persistence.document();
    // A chat the person has talked in stays on its provider: when its key is
    // gone, or its account signed out of, the turn fails rather than carry on
    if (!m_mcp_connect.startup_error.empty())
        payload["startupError"] = m_mcp_connect.startup_error;
    send_envelope(Protocol::kMcpCatalog, payload.dump(), envelope_id);
}

void AgentHost::handle_mcp_preview(const std::string& envelope_id, const std::string& payload_json)
{
    const json payload        = json::parse(payload_json);
    const std::string tool_id = payload.at("toolId").get<std::string>();
    const auto items = mcp_catalog_items();
    const auto found = std::find_if(items.begin(), items.end(), [&](const auto& item) { return item.entry.id == tool_id; });
    // The catalog is a fixed table, and the page can only name an id this host
    // sent it, carrying the cli flag that says which tools have a file to
    // preview at all. Asking to preview anything else is a broken page.
    if (found == items.end() || found->entry.cli)
        throw RuntimeError("jusprin-agent-bridge: mcp_preview names no file-based tool: " + tool_id);
    try {
        const auto value = json::parse(found->entry.text);
        const auto edit = Mcp::prepare_json_connection(found->config_path, found->json_root, value.at(found->json_root).at("jusprin"));
        m_mcp_edit = edit;
        m_mcp_edit_tool = tool_id;
        json payload{{"toolId", tool_id},
                     {"path", edit.path.u8string()},
                     {"next", edit.next.dump(2)},
                     {"root", found->json_root}};
        // "No JusPrin entry yet" is a state, not a value. Serialising it would
        // send the string "null", which the page cannot tell from a real
        // entry; omitting the field says plainly that there is nothing to
        // show, and the page renders that as its own thing.
        if (!edit.previous.is_null())
            payload["previous"] = edit.previous.dump(2);
        send_envelope(Protocol::kMcpPreview, payload.dump(), envelope_id);
    } catch (const Mcp::ConfigRefusal& refusal) {
        send_mcp_status("error", tool_id, envelope_id, {}, AgentError{"write_failed", translated(refusal.what()), true});
    }
}

void AgentHost::handle_mcp_connect(const std::string& envelope_id, const std::string& payload_json)
{
    if (m_mcp_busy) {
        send_bridge_error("busy", translated(L("A connection is already being saved.")), envelope_id);
        return;
    }
    const json payload        = json::parse(payload_json);
    const std::string tool_id = payload.at("toolId").get<std::string>();
    const auto items = mcp_catalog_items();
    const auto found = std::find_if(items.begin(), items.end(), [&](const auto& item) { return item.entry.id == tool_id; });
    if (found == items.end())
        throw RuntimeError("jusprin-agent-bridge: mcp_connect names an unknown tool: " + tool_id);
    if (!std::filesystem::is_regular_file(m_mcp_connect.helper_path)) {
        send_mcp_status("error", tool_id, envelope_id, {},
                        AgentError{"helper_missing", translated(L("JusPrin's connection helper is missing. Reinstall or rebuild JusPrin.")), true});
        return;
    }
    if (!m_mcp_connect.launcher_path.empty() && m_mcp_connect.launcher_path != m_mcp_connect.helper_path &&
        !std::filesystem::is_regular_file(m_mcp_connect.launcher_path)) {
        send_mcp_status("error", tool_id, envelope_id, {},
                        AgentError{"helper_missing", translated(L("The AppImage launcher is missing. Reopen the installed AppImage.")), true});
        return;
    }
    if (!found->entry.cli) {
        if (!m_mcp_edit || m_mcp_edit_tool != tool_id) {
            send_bridge_error("invalid_payload", translated(L("Review the change before connecting.")), envelope_id);
            return;
        }
        send_mcp_status("writing", tool_id, envelope_id);
        try {
            const auto backup = Mcp::apply_config_edit(*m_mcp_edit);
            m_mcp_edit.reset();
            m_mcp_edit_tool.clear();
            if (m_mcp_connect.connected)
                m_mcp_connect.connected();
            send_mcp_status("saved", tool_id, envelope_id, backup.empty() ? "" : backup.u8string());
        } catch (const Mcp::StalePreview& refusal) {
            send_mcp_status("error", tool_id, envelope_id, {}, AgentError{"stale_preview", translated(refusal.what()), true});
        } catch (const Mcp::ConfigRefusal& refusal) {
            send_mcp_status("error", tool_id, envelope_id, {}, AgentError{"write_failed", translated(refusal.what()), true});
        }
        return;
    }
    const auto cli = Mcp::command_on_path(found->entry.id);
    if (cli.empty()) {
        send_mcp_status("error", tool_id, envelope_id, {},
                        AgentError{"cli_missing",
                                   // TRN %1% is an AI client app, such as Claude Code.
                                   Slic3r::format(translated(L("%1% isn't installed. Install it, or copy the command and run it later.")), found->entry.name),
                                   true});
        return;
    }
    if (!m_mcp_cli) {
        send_mcp_status("error", tool_id, envelope_id, {},
                        AgentError{"command_failed", translated(L("This build cannot run the client CLI.")), true});
        return;
    }
    std::vector<std::string> arguments{cli};
    arguments.insert(arguments.end(), found->entry.arguments.begin(), found->entry.arguments.end());
    m_mcp_busy = true;
    send_mcp_status("writing", tool_id, envelope_id);
    m_mcp_cli(arguments, [this, tool_id, envelope_id](bool success, std::string diagnostic) {
        m_mcp_busy = false;
        if (success && m_mcp_connect.connected)
            m_mcp_connect.connected();
        if (success)
            send_mcp_status("saved", tool_id, envelope_id, {}, std::nullopt, diagnostic);
        else {
            const char* code = diagnostic.find("timed out") != std::string::npos ? "timeout" : "command_failed";
            send_mcp_status("error", tool_id, envelope_id, {}, AgentError{code, diagnostic, true}, diagnostic);
        }
    });
}

